def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v not in (0, 5))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = [(r - r0, c - c0) for r, c in points]

    out = [row[:] for row in grid]
    for dr in range(h - max(r for r, c in shape)):
        for dc in range(w - max(c for r, c in shape)):
            cells = [(dr + r, dc + c) for r, c in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = color
    return out
